package com.colddelivery.app.data.local.dao

import androidx.room.*
import com.colddelivery.app.data.local.entity.*
import kotlinx.coroutines.flow.Flow

@Dao interface UserDao { @Query("SELECT * FROM users WHERE id = 1") suspend fun get(): UserEntity?; @Query("SELECT * FROM users WHERE id = 1") fun observe(): Flow<UserEntity?>; @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun upsert(user: UserEntity) }
@Dao interface ProductDao { @Query("SELECT * FROM products WHERE isActive = 1 ORDER BY productName") fun observeActive(): Flow<List<ProductEntity>>; @Query("SELECT COUNT(*) FROM products") suspend fun count(): Int; @Query("SELECT * FROM products WHERE id = :id") suspend fun get(id: Long): ProductEntity?; @Insert(onConflict = OnConflictStrategy.IGNORE) suspend fun insert(product: ProductEntity): Long; @Insert(onConflict = OnConflictStrategy.IGNORE) suspend fun insertAll(products: List<ProductEntity>): List<Long>; @Update suspend fun update(product: ProductEntity) }
@Dao interface StockBatchDao { @Query("SELECT * FROM stock_batches WHERE productId = :productId AND remainingQty > 0 ORDER BY stockInDate ASC, createdAt ASC, id ASC") suspend fun availableFifo(productId: Long): List<StockBatchEntity>; @Query("SELECT * FROM stock_batches WHERE productId = :productId ORDER BY stockInDate ASC, createdAt ASC, id ASC") fun observeForProduct(productId: Long): Flow<List<StockBatchEntity>>; @Query("SELECT * FROM stock_batches WHERE productId = :productId ORDER BY stockInDate ASC, createdAt ASC, id ASC") suspend fun allForProduct(productId: Long): List<StockBatchEntity>; @Query("SELECT COALESCE(SUM(remainingQty), 0) FROM stock_batches WHERE productId = :productId") suspend fun total(productId: Long): Int; @Query("SELECT COALESCE(SUM(initialQty), 0) FROM stock_batches WHERE productId = :productId AND initialQty > 0 AND stockInDate < :date") suspend fun initialStockBefore(productId: Long, date: Long): Int; @Query("SELECT COALESCE(SUM(initialQty), 0) FROM stock_batches WHERE productId = :productId AND initialQty > 0 AND stockInDate = :date") suspend fun stockInOn(productId: Long, date: Long): Int; @Update suspend fun update(batch: StockBatchEntity); @Insert suspend fun insert(batch: StockBatchEntity): Long; @Insert suspend fun insertAll(batches: List<StockBatchEntity>): List<Long>; @Query("SELECT * FROM stock_batches WHERE id = :id") suspend fun get(id: Long): StockBatchEntity?; @Query("SELECT COALESCE(SUM(remainingQty), 0) FROM stock_batches") fun observeTotal(): Flow<Int> }
@Dao interface CustomerDao { @Query("SELECT * FROM customers WHERE isActive = 1 ORDER BY deliveryDay, sortOrder, name") fun observeActive(): Flow<List<CustomerEntity>>; @Query("SELECT * FROM customers WHERE isActive = 1 AND deliveryDay = :day ORDER BY sortOrder, name") fun observeForDay(day: String): Flow<List<CustomerEntity>>; @Query("SELECT * FROM customers WHERE isActive = 1 AND deliveryDay = :day ORDER BY sortOrder, name") suspend fun orderedForDay(day: String): List<CustomerEntity>; @Query("SELECT * FROM customers WHERE id = :id") suspend fun get(id: Long): CustomerEntity?; @Insert suspend fun insert(customer: CustomerEntity): Long; @Insert suspend fun insertAll(customers: List<CustomerEntity>): List<Long>; @Update suspend fun update(customer: CustomerEntity) }
@Dao interface DailyPriceDao { @Query("SELECT * FROM daily_prices WHERE priceDate = :date") fun observeForDate(date: Long): Flow<List<DailyPriceEntity>>; @Query("SELECT * FROM daily_prices WHERE productId = :productId AND priceDate = :date") suspend fun get(productId: Long, date: Long): DailyPriceEntity?; @Insert(onConflict = OnConflictStrategy.REPLACE) suspend fun upsert(price: DailyPriceEntity) }
@Dao interface DeliveryDao { @Query("SELECT * FROM deliveries WHERE isDeleted = 0 ORDER BY deliveryDate DESC, createdAt DESC") fun observeHistory(): Flow<List<DeliveryEntity>>; @Query("SELECT * FROM deliveries WHERE id = :id") suspend fun get(id: Long): DeliveryEntity?; @Query("SELECT * FROM deliveries WHERE customerId = :customerId AND deliveryDate = :date AND isDeleted = 0 LIMIT 1") suspend fun forCustomerOnDate(customerId: Long, date: Long): DeliveryEntity?; @Query("SELECT customerId FROM deliveries WHERE deliveryDate = :date AND status = 'DELIVERED' AND isDeleted = 0") fun observeDeliveredCustomerIds(date: Long): Flow<List<Long>>; @Insert suspend fun insert(delivery: DeliveryEntity): Long; @Update suspend fun update(delivery: DeliveryEntity) }
data class HistoricalDeliveryMovement(val customerName: String, val quantity: Int, val deliveryDate: Long)
@Dao interface DeliveryItemDao { @Query("SELECT * FROM delivery_items WHERE deliveryId = :deliveryId") suspend fun forDelivery(deliveryId: Long): List<DeliveryItemEntity>; @Query("SELECT COALESCE(SUM(di.qty), 0) FROM delivery_items di INNER JOIN deliveries d ON d.id = di.deliveryId WHERE di.productId = :productId AND d.deliveryDate < :date AND d.status = 'DELIVERED' AND d.isDeleted = 0") suspend fun deliveredBefore(productId: Long, date: Long): Int; @Query("SELECT COALESCE(SUM(di.qty), 0) FROM delivery_items di INNER JOIN deliveries d ON d.id = di.deliveryId WHERE di.productId = :productId AND d.deliveryDate = :date AND d.status = 'DELIVERED' AND d.isDeleted = 0") suspend fun deliveredOn(productId: Long, date: Long): Int; @Query("SELECT c.name AS customerName, di.qty AS quantity, d.deliveryDate AS deliveryDate FROM delivery_items di INNER JOIN deliveries d ON d.id = di.deliveryId INNER JOIN customers c ON c.id = d.customerId WHERE di.productId = :productId AND d.deliveryDate = :date AND d.status = 'DELIVERED' AND d.isDeleted = 0 ORDER BY d.createdAt ASC, d.id ASC") suspend fun movementsOn(productId: Long, date: Long): List<HistoricalDeliveryMovement>; @Insert suspend fun insert(item: DeliveryItemEntity): Long; @Update suspend fun update(item: DeliveryItemEntity); @Query("DELETE FROM delivery_items WHERE deliveryId = :deliveryId") suspend fun deleteForDelivery(deliveryId: Long) }
@Dao interface FifoAllocationDao { @Query("SELECT * FROM fifo_allocations WHERE deliveryItemId = :itemId") suspend fun forItem(itemId: Long): List<FifoAllocationEntity>; @Insert suspend fun insert(allocation: FifoAllocationEntity); @Query("DELETE FROM fifo_allocations WHERE deliveryItemId = :itemId") suspend fun deleteForItem(itemId: Long) }
